CryoLean.accept_all_coupled {cfg : CryoLean.Configuration} {e : CryoLean.Experiment}
  (h : CryoLean.verdict cfg e = CryoLean.Verdict.accept) (c : CryoLean.Coupled) :
  c ∈ e.coupled → c.mandatory = true → c.applicable = true → CryoLean.CoupledOK cfg e c

CryoLean.accept_no_unknown {cfg : CryoLean.Configuration} {e : CryoLean.Experiment}
  (h : CryoLean.verdict cfg e = CryoLean.Verdict.accept) (o : CryoLean.Outcome) :
  o ∈ CryoLean.outcomes cfg e → o ≠ CryoLean.Outcome.unknown ∧ o ≠ CryoLean.Outcome.unsupported

CryoLean.cap_not_usable_missing {cfg : CryoLean.Configuration} {e : CryoLean.Experiment} {key : String}
  {s : CryoLean.Sel} {c : CryoLean.Capability} (hl : CryoLean.lookup cfg key = some c)
  (hu : CryoLean.usable c = false) : CryoLean.evalExpr cfg e (CryoLean.Expr.cap key s) = CryoLean.EvalR.missing key

CryoLean.condition_false_not_applicable {cfg : CryoLean.Configuration} {e : CryoLean.Experiment}
  {r : CryoLean.Requirement} (h : ∃ c, c ∈ r.conditions ∧ CryoLean.CondFails cfg e c) :
  CryoLean.checkRequirement cfg e r = CryoLean.Outcome.notApplicable

CryoLean.not_installed_never_passes {k : CryoLean.Constraint} {c : CryoLean.Capability}
  (h : c.install = CryoLean.InstallStatus.optionalNotInstalled) (hk : k ≠ CryoLean.Constraint.flagIs false) :
  CryoLean.checkCapability k c ≠ CryoLean.Outcome.pass

CryoLean.pass_implies_dims_match {q m : CryoLean.Quantity}
  (h : CryoLean.checkValue (CryoLean.Constraint.atLeast q) (CryoLean.CapValue.max m) = CryoLean.Outcome.pass) :
  m.dim = q.dim

CryoLean.pass_dims_all_match {k : CryoLean.Constraint} {v : CryoLean.CapValue}
  (h : CryoLean.checkValue k v = CryoLean.Outcome.pass) :
  ∃ D, (∀ (d : CryoLean.Dim), d ∈ k.dims → d = D) ∧ ∀ (d : CryoLean.Dim), d ∈ CryoLean.comparedDims k v → d = D

CryoLean.validSchedule_sound {cfg : CryoLean.Configuration} {exps : List CryoLean.Experiment}
  {slots : List CryoLean.Slot} {L : CryoLean.Quantity} (h : CryoLean.validSchedule cfg exps slots L = true) :
  CryoLean.ScheduleOK cfg exps slots L

CryoLean.validSchedule_complete {cfg : CryoLean.Configuration} {exps : List CryoLean.Experiment}
  {slots : List CryoLean.Slot} {L : CryoLean.Quantity} (h : CryoLean.ScheduleOK cfg exps slots L) :
  CryoLean.validSchedule cfg exps slots L = true

CryoLean.validSchedule_disjoint {cfg : CryoLean.Configuration} {exps : List CryoLean.Experiment}
  {slots : List CryoLean.Slot} {L : CryoLean.Quantity} (h : CryoLean.validSchedule cfg exps slots L = true) :
  ∃ ps, CryoLean.resolve exps slots = some ps ∧ List.Pairwise CryoLean.Disjoint ps

CryoLean.validSchedule_only_accepted {cfg : CryoLean.Configuration} {exps : List CryoLean.Experiment}
  {slots : List CryoLean.Slot} {L : CryoLean.Quantity} (h : CryoLean.validSchedule cfg exps slots L = true)
  (e : CryoLean.Experiment) : e ∈ exps → CryoLean.AcceptSpec cfg e

CryoLean.validSchedule_rejects_unaccepted {cfg : CryoLean.Configuration} {exps : List CryoLean.Experiment}
  {slots : List CryoLean.Slot} {L : CryoLean.Quantity} {e : CryoLean.Experiment} (he : e ∈ exps)
  (hv : CryoLean.verdict cfg e ≠ CryoLean.Verdict.accept) : CryoLean.validSchedule cfg exps slots L = false
